// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.infrastructureimport timber.log.Timberimport com.roshan.persona.vision.core.ConfidenceTierimport com.roshan.persona.vision.core.ConfidenceTieredResultimport com.roshan.persona.vision.core.OmniSlmRuntimeimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContext/** * NOUS — Fallback Chain Orchestrator (Module 6 v4 — Step 6.7, CRITICAL). * * Implements the **fallback chain** for vision engines, per strategy v4 §"Issue 3: * Missing Error Handling & Recovery Paths" + §"Issue 1: Confidence Thresholds". * * ## Why this matters * * v3 defined success paths only. v4 defines what happens when models fail: * * | Engine | Primary | Fallback 1 | Fallback 2 | Final | * |--------|---------|-----------|-----------|-------| * | Camera Intelligence | Omni-SLM | ObjectDetection (SSD) | ImageClassification | "I'm not sure what I'm looking at" | * | Screen Understanding | UiElementDetector | OcrEngine (full text) | "I can't read anything on this screen" | Template summary | * | OCR | ML Kit | TFLite OCR (if available) | "I couldn't read this clearly. Please hold steady and try again." | Empty result | * | Embedding | Omni-SLM | MiniLM-L6 (v2 stack) | TfIdfEmbedder (Brain fallback) | Failure | * | NER | Omni-SLM | BERT-tiny (v2 stack) | RegexPostProcessor (Brain fallback) | Empty list | * * ## Camera Intelligence Fallback Chain (per v4 §"Issue 1") * * ``` * 1. ObjectDetectionEngine (SSD) → if < 3 objects detected → fallback to ImageClassification * 2. ImageClassification → if confidence < 0.5 → fallback to ImageCaptioning (Omni-SLM) * 3. ImageCaptioning → if fails → fallback to "I'm not sure what I'm looking at" * ``` * * ## Screen Understanding Fallback Chain * * ``` * 1. UiElementDetector → if < 5 elements → fallback to OcrEngine (full text extraction) * 2. OcrEngine → if no text → fallback to "I can't read anything on this screen" * 3. ScreenSummarizer (LLM) → if LLM fails → fallback to template: "Found [N] elements: [list]" * ``` * * ## OCR Error Recovery (per v4 §"Issue 3") * * | Error | Recovery | User Feedback | * |-------|----------|---------------| * | NNAPI delegate init fails | Fallback to CPU interpreter | "Processing on CPU (slower but accurate)" | * | OCR returns empty/gibberish | Retry with enhanced preprocessing | "I couldn't read this clearly. Please hold steady and try again." | * | ML Kit crash | Catch exception → fallback to TFLite OCR | "OCR is temporarily unavailable. Please try again." | * | FaceDetectionEngine timeout | Skip face detection; proceed with other engines | "Face detection timed out. Continuing with other analysis." | * * ## Testability * * [VisionEngineChain] abstracts the actual engine calls. Tests inject * [FakeVisionEngineChain] to simulate success/failure scenarios. * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Issue 1: Confidence Thresholds + §Issue 3: Error Handling</a> */class FallbackChainOrchestrator(    private val chain: VisionEngineChain,    private val dispatcher: CoroutineDispatcher,) {    /**     * Run the Camera Intelligence fallback chain.     *     * Tries: ObjectDetection → ImageClassification → ImageCaptioning → "I'm not sure".     *     * @param imageBytes the camera frame.     * @return the best result with fallback info (if fallback was used).     */    suspend fun runCameraIntelligenceChain(imageBytes: ByteArray): FallbackResult<CameraIntelligenceResult> =        withContext(dispatcher) {            Timber.tag(TAG).d("Running camera intelligence fallback chain.")            // Step 1: Object Detection (SSD).            val detectionResult = try {                chain.runObjectDetection(imageBytes)            } catch (t: Throwable) {                Timber.tag(TAG).w("Object detection failed — falling back to classification.", t)                null            }            val detectionValue = detectionResult?.value            if (detectionResult != null && detectionResult.isSuccess &&                detectionValue != null && detectionValue.objectCount >= 3) {                return@withContext FallbackResult.success(                    CameraIntelligenceResult(                        label = detectionValue.topLabel,                        confidence = detectionValue.topConfidence,                        source = IntelligenceSource.OBJECT_DETECTION,                        allObjects = detectionValue.allLabels,                    )                )            }            // Step 2: Image Classification (fallback if < 3 objects or detection failed).            Timber.tag(TAG).d("Falling back to image classification (detection=${detectionResult?.isSuccess}, objects=${detectionResult?.value?.objectCount}).")            val classificationResult = try {                chain.runImageClassification(imageBytes)            } catch (t: Throwable) {                Timber.tag(TAG).w("Image classification failed — falling back to captioning.", t)                null            }            val classificationValue = classificationResult?.value            if (classificationResult != null && classificationResult.isSuccess &&                classificationValue != null && classificationValue.confidence >= 0.50f) {                return@withContext FallbackResult.fallback(                    CameraIntelligenceResult(                        label = classificationValue.label,                        confidence = classificationValue.confidence,                        source = IntelligenceSource.IMAGE_CLASSIFICATION,                        allObjects = detectionResult?.value?.allLabels ?: emptyList(),                    ),                    fallbackReason = "Object detection returned < 3 objects",                )            }            // Step 3: Image Captioning (Omni-SLM — fallback if classification < 0.5).            Timber.tag(TAG).d("Falling back to image captioning (classification confidence < 0.5).")            val captionResult = try {                chain.runImageCaptioning(imageBytes)            } catch (t: Throwable) {                Timber.tag(TAG).w("Image captioning failed — final fallback.", t)                null            }            val captionValue = captionResult?.value            if (captionResult != null && captionResult.isSuccess && captionValue != null) {                return@withContext FallbackResult.fallback(                    CameraIntelligenceResult(                        label = captionValue.caption,                        confidence = captionValue.confidence,                        source = IntelligenceSource.IMAGE_CAPTIONING,                        allObjects = detectionResult?.value?.allLabels ?: emptyList(),                    ),                    fallbackReason = "Classification confidence < 0.5",                )            }            // Step 4: Final fallback — "I'm not sure".            Timber.tag(TAG).w("All camera intelligence engines failed — returning uncertain result.")            return@withContext FallbackResult.fallback(                CameraIntelligenceResult(                    label = "I'm not sure what I'm looking at",                    confidence = 0.0f,                    source = IntelligenceSource.UNKNOWN,                    allObjects = emptyList(),                ),                fallbackReason = "All engines failed",            )        }    /**     * Run the Screen Understanding fallback chain.     *     * Tries: UiElementDetection → OCR (full text) → "I can't read anything".     *     * @param screenshotBytes the screenshot image.     * @return the best result with fallback info.     */    suspend fun runScreenUnderstandingChain(screenshotBytes: ByteArray): FallbackResult<ScreenUnderstandingFallbackResult> =        withContext(dispatcher) {            Timber.tag(TAG).d("Running screen understanding fallback chain.")            // Step 1: UI Element Detection.            val uiResult = try {                chain.runUiElementDetection(screenshotBytes)            } catch (t: Throwable) {                Timber.tag(TAG).w("UI element detection failed — falling back to OCR.", t)                null            }            val uiValue = uiResult?.value            if (uiResult != null && uiResult.isSuccess &&                uiValue != null && uiValue.elementCount >= 5) {                return@withContext FallbackResult.success(                    ScreenUnderstandingFallbackResult(                        elementCount = uiValue.elementCount,                        text = uiValue.allText,                        source = ScreenUnderstandingSource.UI_DETECTION,                    )                )            }            // Step 2: OCR (full text extraction — fallback if < 5 elements).            Timber.tag(TAG).d("Falling back to OCR (UI elements < 5).")            val ocrResult = try {                chain.runOcr(screenshotBytes)            } catch (t: Throwable) {                Timber.tag(TAG).w("OCR failed — final fallback.", t)                null            }            val ocrValue = ocrResult?.value            if (ocrResult != null && ocrResult.isSuccess &&                ocrValue != null && ocrValue.text.isNotBlank()) {                return@withContext FallbackResult.fallback(                    ScreenUnderstandingFallbackResult(                        elementCount = uiResult?.value?.elementCount ?: 0,                        text = ocrValue.text,                        source = ScreenUnderstandingSource.OCR,                    ),                    fallbackReason = "UI detection returned < 5 elements",                )            }            // Step 3: Final fallback — "I can't read anything".            Timber.tag(TAG).w("Screen understanding: no text or elements detected.")            return@withContext FallbackResult.fallback(                ScreenUnderstandingFallbackResult(                    elementCount = 0,                    text = "I can't read anything on this screen",                    source = ScreenUnderstandingSource.UNKNOWN,                ),                fallbackReason = "No text or UI elements detected",            )        }    /**     * Run the Embedding fallback chain.     *     * Tries: Omni-SLM → MiniLM-L6 (v2 stack) → TfIdfEmbedder (Brain fallback).     *     * @param text the text to embed.     * @return the embedding with fallback info.     */    suspend fun runEmbeddingChain(text: String): FallbackResult<FloatArray> = withContext(dispatcher) {        Timber.tag(TAG).d("Running embedding fallback chain for: ${text.take(50)}...")        // Step 1: Omni-SLM.        val omniSlmResult = try {            chain.embedViaOmniSlm(text)        } catch (t: Throwable) {            Timber.tag(TAG).w("Omni-SLM embedding failed — falling back to MiniLM.", t)            null        }        val omniSlmValue = omniSlmResult?.value        if (omniSlmResult != null && omniSlmResult.isSuccess && omniSlmValue != null) {            return@withContext FallbackResult.success(omniSlmValue)        }        // Step 2: MiniLM-L6 (v2 stack).        Timber.tag(TAG).d("Falling back to MiniLM-L6.")        val miniLmResult = try {            chain.embedViaMiniLm(text)        } catch (t: Throwable) {            Timber.tag(TAG).w("MiniLM embedding failed — falling back to TfIdf.", t)            null        }        val miniLmValue = miniLmResult?.value        if (miniLmResult != null && miniLmResult.isSuccess && miniLmValue != null) {            return@withContext FallbackResult.fallback(                miniLmValue,                fallbackReason = "Omni-SLM failed",            )        }        // Step 3: TfIdf (Brain fallback — always succeeds but low quality).        Timber.tag(TAG).w("Falling back to TfIdf embedder (low quality).")        val tfIdfResult = try {            chain.embedViaTfIdf(text)        } catch (t: Throwable) {            Timber.tag(TAG).e("TfIdf embedding also failed — returning failure.", t)            return@withContext FallbackResult.failure("All embedding engines failed")        }        return@withContext FallbackResult.fallback(            tfIdfResult,            fallbackReason = "Omni-SLM + MiniLM failed",        )    }    private companion object {        private const val TAG = "FallbackChain"    }}// ──────────────────────────────────────────────────────────────────────────/** Result of a fallback chain execution. */data class FallbackResult<T>(    val value: T?,    val success: Boolean,    val fallbackUsed: Boolean,    val fallbackReason: String? = null,) {    val isUsable: Boolean get() = success && value != null    companion object {        fun <T> success(value: T): FallbackResult<T> = FallbackResult(            value = value,            success = true,            fallbackUsed = false,        )        fun <T> fallback(value: T, fallbackReason: String): FallbackResult<T> = FallbackResult(            value = value,            success = true,            fallbackUsed = true,            fallbackReason = fallbackReason,        )        fun <T> failure(reason: String): FallbackResult<T> = FallbackResult(            value = null,            success = false,            fallbackUsed = true,            fallbackReason = reason,        )    }}/** Camera intelligence result. */data class CameraIntelligenceResult(    val label: String,    val confidence: Float,    val source: IntelligenceSource,    val allObjects: List<String>,)/** Source of camera intelligence. */enum class IntelligenceSource(val displayName: String) {    OBJECT_DETECTION("Object Detection (SSD)"),    IMAGE_CLASSIFICATION("Image Classification"),    IMAGE_CAPTIONING("Image Captioning (Omni-SLM)"),    UNKNOWN("Unknown"),}/** Screen understanding result. */data class ScreenUnderstandingFallbackResult(    val elementCount: Int,    val text: String,    val source: ScreenUnderstandingSource,)/** Source of screen understanding. */enum class ScreenUnderstandingSource(val displayName: String) {    UI_DETECTION("UI Element Detection"),    OCR("OCR (Full Text)"),    UNKNOWN("Unknown"),}// ──────────────────────────────────────────────────────────────────────────/** Detection result wrapper. */data class DetectionChainResult(    val objectCount: Int,    val topLabel: String,    val topConfidence: Float,    val allLabels: List<String>,)/** Classification result wrapper. */data class ClassificationChainResult(    val label: String,    val confidence: Float,)/** Captioning result wrapper. */data class CaptionChainResult(    val caption: String,    val confidence: Float,)/** UI element detection result wrapper. */data class UiElementChainResult(    val elementCount: Int,    val allText: String,)/** OCR result wrapper. */data class OcrChainResult(    val text: String,)// ──────────────────────────────────────────────────────────────────────────/** * Vision engine chain interface — abstracts the actual engine calls. * * Production: [VisionEngineChainImpl] wraps ObjectDetector + OmniSlmRuntime + * OcrEngine + UiElementDetector. * Tests: [FakeVisionEngineChain] returns canned results. */interface VisionEngineChain {    suspend fun runObjectDetection(imageBytes: ByteArray): ConfidenceTieredResult<DetectionChainResult>?    suspend fun runImageClassification(imageBytes: ByteArray): ConfidenceTieredResult<ClassificationChainResult>?    suspend fun runImageCaptioning(imageBytes: ByteArray): ConfidenceTieredResult<CaptionChainResult>?    suspend fun runUiElementDetection(imageBytes: ByteArray): ConfidenceTieredResult<UiElementChainResult>?    suspend fun runOcr(imageBytes: ByteArray): ConfidenceTieredResult<OcrChainResult>?    suspend fun embedViaOmniSlm(text: String): ConfidenceTieredResult<FloatArray>?    suspend fun embedViaMiniLm(text: String): ConfidenceTieredResult<FloatArray>?    suspend fun embedViaTfIdf(text: String): FloatArray}